drop function if exists hrm.todo_employment_assignments_cost_allocation_sum();
create or replace function hrm.tg_employment_assignments_cost_allocation_sum() returns trigger
language plpgsql as $fn$
declare
    item jsonb;
    share numeric;
    total numeric := 0;
begin
    if jsonb_typeof(new.cost_allocation) is distinct from 'array' or jsonb_array_length(new.cost_allocation) = 0 then
        raise exception 'cost allocation of assignment % must be a non-empty list', new.id
            using errcode = '23514', constraint = 'ck_employment_assignments_cost_allocation_sum';
    end if;
    for item in select value from jsonb_array_elements(new.cost_allocation) loop
        if jsonb_typeof(item) is distinct from 'object' or jsonb_typeof(item -> 'pct') is distinct from 'number'
           or (item ? 'cost_center_ref') = (item ? 'department') then
            raise exception 'cost allocation of assignment % has a share without exactly one target and a number', new.id
                using errcode = '23514', constraint = 'ck_employment_assignments_cost_allocation_sum';
        end if;
        share := (item ->> 'pct')::numeric;
        if share <= 0 or share > 1 then
            raise exception 'cost allocation of assignment % has a share of %', new.id, share
                using errcode = '23514', constraint = 'ck_employment_assignments_cost_allocation_sum';
        end if;
        total := total + share;
    end loop;
    if total <> 1 then
        raise exception 'cost allocation of assignment % sums to % instead of 1', new.id, total
            using errcode = '23514', constraint = 'ck_employment_assignments_cost_allocation_sum';
    end if;
    return new;
end
