-- hrm.employment_assignments: Cycle check trigger on manager_employment_id.
drop function if exists hrm.todo_employment_assignments_manager_cycle();
create or replace function hrm.tg_employment_assignments_manager_cycle() returns trigger
language plpgsql as $fn$
declare
    d date;
begin
    if new.manager_employment_id is null then
        return null;
    end if;
    if new.manager_employment_id = new.employment_id then
        raise exception 'employment % cannot be its own manager', new.employment_id
            using errcode = '23514', constraint = 'ck_employment_assignments_manager_cycle';
    end if;
    if not exists (
        with recursive up(id) as (
            select new.manager_employment_id
            union
            select a.manager_employment_id from hrm.employment_assignments a join up on a.employment_id = up.id
            where a.manager_employment_id is not null)
        select 1 from up where up.id = new.employment_id) then
        return null;
    end if;
    for d in
        with recursive up(id) as (
            select new.manager_employment_id
            union
            select a.manager_employment_id from hrm.employment_assignments a join up on a.employment_id = up.id
            where a.manager_employment_id is not null)
        select new.valid_from
        union
        select a.valid_from from hrm.employment_assignments a
        where a.employment_id in (select id from up) and a.valid_from > new.valid_from
          and (new.valid_to is null or a.valid_from < new.valid_to)
    loop
        if exists (
            with recursive chain(id) as (
                select new.manager_employment_id
                union
                select a.manager_employment_id from chain c join hrm.employment_assignments a on a.employment_id = c.id
                where a.manager_employment_id is not null and a.valid_from <= d and (a.valid_to is null or a.valid_to > d))
            select 1 from chain where chain.id = new.employment_id) then
            raise exception 'manager % of employment % on % closes a reporting cycle', new.manager_employment_id, new.employment_id, d
                using errcode = '23514', constraint = 'ck_employment_assignments_manager_cycle';
        end if;
    end loop;
    return null;
end
